class Solution {
public:
    bool isValid(string s) {
        stack<char> st;
        for(auto c: s) {
            if(c == ')' and !st.empty() and st.top() == '(') st.pop(); 
            else if(c == '}' and !st.empty() and st.top() == '{') st.pop(); 
            else if(c == ']' and !st.empty() and st.top() == '[') st.pop(); 
            else st.push(c);
        }
        if(st.empty()) return true;
        else return false;
    }
