class Solution {
public:
    int searchInsert(vector<int>& nums, int target) {

        int n = nums.size();

        // apply binary search

        int low = 0;

        int high = n - 1;

        int idx = n;

        while(low <= high)
        {
            // find mid

            int mid = low + (high - low) / 2;

            // check the conditions and update the idx and move pointers accordingly

            if(nums[mid] >= target)
            {
                idx = mid;

                high = mid - 1;
            }
            else
            {
                low = mid + 1;
            }
        }

        return idx;
    }
};,23,https://leetcode.com/problems/search-insert-position,https://leetcode.com/problems/search-insert-position/solutions/3208153/c-binary-search-faster-easy-to-understand/,13,35,cpp

class Solution {
public:
    void solve(vector<int>& candidates, int target, int i, vector<vector<int>>& ans, vector<int>& output){
        //base case
        if(target == 0){
            ans.push_back(output);
            return;
        }

        int prev = -1;
        for(int j=i; j<candidates.size(); j++){
            if(candidates[j] != prev && candidates[j] <= target){
                output.push_back(candidates[j]);
                solve(candidates, target-candidates[j], j+1, ans, output);
                output.pop_back();
                prev = candidates[j];
            }
        }

    }


    vector<vector<int>> combinationSum2(vector<int>& candidates, int target) {
        sort(candidates.begin(), candidates.end());
        vector<vector<int>> ans;
        vector<int> output;
        int i = 0;
        solve(candidates, target, i, ans, output);
        return ans;
    }
