class Solution {
public:
    int mySqrt(int x) {
        if(x == 1)
            return 1;
        int low = 0;
        int high = x/2;
        int ans;

        while(low <= high) {
            long long mid = low + (high-low)/2;
            long long sq = mid*mid;

            if(sq <= x) {
                ans = mid;
                low = mid+1;
            }
            else {
                high = mid-1;
            }
        }

        return ans;
    }
};,90,https://leetcode.com/problems/sqrtx,https://leetcode.com/problems/sqrtx/solutions/3940338/optimized-approach-using-binary-search/,23,69,cpp

class Solution {
public:
    string simplifyPath(string s) {
        list<string> lst;
        string ans = "",str = "";
        for(int i = 0;i<s.size();i++)
        {
            if(s[i]=='/' || i==s.size()-1)
            {
                if(i==s.size()-1 && s[i]!='/') str+=s[i];
                if(str.size()>0)
                {
                    if(str==".." && lst.size()>0) lst.pop_back();
                    else if(str!="." && str!="..") lst.push_back(str);
                }
                str = "";
            }
            else str+=s[i];
        }
        while(!lst.empty())
        {
            ans+="/"+lst.front();
            lst.pop_front();
        }
        return ans.size()==0 ? "/" : ans;   
    }
