var subsets = function(nums) {
    const output = [[]];
    const hashmap = new Map();

    const backtracking = (curr, remaining, target) => {
        if (!target) {
            const key = curr.sort((a, b) => a - b).toString();
            if (!hashmap.has(key)) {
                output.push(curr);
                hashmap.set(key, 1);
            }
            return;
        }

        for (let i = 0; i < remaining.length; i++) {
            const item = remaining[i];
            const newCurr = [...curr];
            const newRemaining = [...remaining];

            newCurr.push(item);
            newRemaining.splice(0, i + 1)

            backtracking(newCurr, newRemaining, target - 1);
        }
    }

    for (let i = 1; i <= nums.length; i++) {
        backtracking([], nums, i);
    }

    return output;
