                dp[i][j] = M[i][j] == '1' ? dp[i][j+1] + 1 : 0;

        for(int i = 0; i < m; i++) 
            for(int j = 0; j < n; j++) 
                for(int row = i, colLen = n; row < m && M[row][j] == '1'; row++)
                    ans = max(ans, (row-i+1) * (colLen = min(colLen, dp[row][j]*1)));

        return ans;
    }
