#pragma GCC optimize("O3", "unroll-loops")
class Solution {
public:
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> ans;
        vector<TreeNode*> stack;
        TreeNode* ptr=root;
        for(; ptr||!stack.empty(); ptr=ptr->right){
            for (; ptr; ptr=ptr->left)
                stack.push_back(ptr);
            ptr=stack.back();
            stack.pop_back();
            ans.push_back(ptr->val);
        }
        return ans;
    }
};
