class Solution {
public:
    vector<TreeNode*> generateTrees(int n , int s =1) {

        if(s>n || s<1)
        {
            return {NULL};
        }
        vector<TreeNode*> res;

        for(int i=s;i<=n;i++)
        {
            // cout<<i<<endl;
            vector<TreeNode*> l = generateTrees(i-1,s);
            vector<TreeNode*> r = generateTrees(n,i+1);

            for(auto ll : l)
            {
                for(auto rr: r)
                {
                    TreeNode *r = new TreeNode(i);
                    r->left = ll;
                    r->right = rr;
                    res.push_back(r);
                }
            }
        }

        return res;


    }
