class Solution {
public:
    void recoverTree(TreeNode* root) {

       TreeNode * prev=NULL;
       TreeNode * first=NULL;
       TreeNode * second = NULL;

      vector<int> res;
        //create a current node to save root
        TreeNode* curr = root;

        //iterate over whole tree
        while(curr!=NULL){
            //if left node of tree is null simply print data and move right
            if(curr->left==NULL){
                //store index of the wrong node
                if(prev!=NULL && prev->val>curr->val){
                    if(first!=NULL){
                        second = curr;
                    }
                    else{
                        first=prev;
                        second=curr;
                    }
                }

                prev = curr;
                //move right
                curr=curr->right;

            }// if left node of tree is not null then find the rightmost node of the subtree
            else{
                //create a temp node
                TreeNode* temp = curr->left;
                //move to the temp node till the time we find rightmost node or find that current node is already not traversed
                while(temp->right!=NULL && temp->right!=curr){
                    temp=temp->right;
                }
                //next right element is NULL so create a link
                if(temp->right==NULL){
                    temp->right=curr;
                    curr=curr->left;
                }
                //already traversed the left side break the loop
                else{
                    temp->right=NULL;
                     //store index of the wrong node
                    if(prev!=NULL && prev->val>curr->val){
                    if(first!=NULL){
                        second = curr;
                    }
                    else{
                        first=prev;
                        second=curr;
                    }
                }

                    prev = curr;
                    //move right
                    curr=curr->right;
                }
            }
        } 

        //swap data of node to get the data at it's right place
        int temp  = first->val;
        first->val = second->val;
        second->val = temp;

    }
