class Solution{
public: 
TreeNode* modify(TreeNode* A) {
    if(!A) return NULL; 
    if(!A->left && !A->right) return A; 
    if(!A->left){
        A->right = modify(A->right); 
        return A; 
    }
    if(!A->right){
        A->right = modify(A->left); 
        A->left = NULL; 
        return A; 
    }

    TreeNode* l, *r; l = modify(A->left); r = modify(A->right); 
    TreeNode* cursor = l; 
    while(cursor->right) cursor = cursor->right; 
    cursor->right = r; 

    A->left = NULL; A->right = l; 

    return A; 


}

void flatten(TreeNode* root){

    root = modify(root); 
}

