            if(s[i] == t[0]) dp[i][0] = (dp[i-1][0]%mod + 1)%mod;
            else dp[i][0] = dp[i-1][0];
        }

        for(int i = 1; i < m; i++) {
            for(int j = 1; j < n; j++) {
                if(s[i] == t[j]) dp[i][j] = (dp[i-1][j]%mod + dp[i-1][j-1]%mod)%mod;
                else dp[i][j] = dp[i-1][j];
            }
        }
        return dp[m-1][n-1];
    }
