class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        int n = nums.size();

        // Step 1: Sort the input vector in ascending order.
        sort(nums.begin(), nums.end());

        // Step 2: Handle the base case when the vector is empty.
        if (n == 0) {
            return 0;
        }

        int last_number = INT_MIN;  // Initialize a variable to track the last processed number.
        int cnt = 0;                // Initialize a counter for the current consecutive sequence length.
        int longest = 1;            // Initialize a variable to store the maximum consecutive sequence length.

        // Step 3: Iterate through the sorted vector.
        for (int i = 0; i < n; i++) {
            if (nums[i] - 1 == last_number) {
                // Step 4: If the current number is consecutive to the previous one, increment the counter.
                cnt++;
                last_number = nums[i];
            } else if (nums[i] != last_number) {
                // Step 5: If the current number is not consecutive, update 'cnt' and 'last_number'.
                cnt = 1;
                last_number = nums[i];
            }

            // Step 6: Update 'longest' with the maximum of 'longest' and 'cnt'.
            longest = max(longest, cnt);
        }

        // Step 7: Return 'longest' as the result, representing the length of the longest consecutive sequence.
        return longest;
    }
};

