    ListNode divide(ListNode h){
        if(h==null||h.next==null) return h;
        ListNode s=h;
        ListNode f=h;
        while(f.next!=null&&f.next.next!=null){
            s=s.next;
            f=f.next.next;
        }
       ListNode t=s.next;
       s.next=null;
       ListNode g=divide(h);
      ListNode d=divide(t);
     return  merge(g,d);
