      if(h.val<t.val){
          q.next=h;
          h=h.next;
      }
      else{ 
          q.next=t;
          t=t.next;
      }
      q=q.next;
      }
      if(h!=null){
          q.next=h;
      }
      if(t!=null){
          q.next=t;
      }
