class Trie {
public:
    Trie() {

    }

    // create structure of TrieNode

    struct TrieNode
    {
        bool end;

        TrieNode* child[26];

        TrieNode()
        {
            end = false;

            for(int i = 0; i < 26; i++)
            {
                child[i] = NULL;
            }
        }
    };

    // create root of the Trie

    TrieNode* root = new TrieNode();

    // function for inserting word in the trie

    void insert(string word) {

        int n = word.size();

        TrieNode* curr = root;

        for(int i = 0; i < n; i++)
        {
            int idx = word[i] - 'a';

            if(curr -> child[idx] == NULL)
            {
                curr -> child[idx] = new TrieNode();
            }

            curr = curr -> child[idx];
        }

        curr -> end = true;
    }

    // function for searching the word in the trie

    bool search(string word) {

        int n = word.size();

        TrieNode* curr = root;

        for(int i = 0; i < n; i++)
        {
            int idx = word[i] - 'a';

            if(curr -> child[idx] == NULL)
                return false;

            curr = curr -> child[idx];
        }

        return curr -> end;
    }

    bool startsWith(string prefix) {

        int n = prefix.size();

        TrieNode* curr = root;

        for(int i = 0; i < n; i++)
        {
            int idx = prefix[i] - 'a';

            if(curr -> child[idx] == NULL)
                return false;

            curr = curr -> child[idx];
        }

        return true;
    }
};,23,https://leetcode.com/problems/implement-trie-prefix-tree,https://leetcode.com/problems/implement-trie-prefix-tree/solutions/3305911/c-trie-faster-easy-to-understand/,81,208,cpp

class Solution {

    /*
        Time Complexity : O(N)
        Space Complexity : O(1)
    */

public:
    int minSubArrayLen(int target, vector<int>& nums) {
        int start = 0, end = 0, n = nums.size();
        int res = INT_MAX, currSum = 0;

        for(end=0; end<n; end++){
            currSum += nums[end];

            while(currSum >= target){
                res = min(res, end-start+1);

                currSum -= nums[start];
                start++;
            }
        }

        return res == INT_MAX ? 0 : res;
    }
