class Solution {
public:
    vector<int> findOrder(int n, vector<vector<int>>& prerequisites) {
        vector<vector<int>> adj(n);
        vector<int> degree(n,0),ans;
        for(auto x:prerequisites){
            adj[x[1]].push_back(x[0]);
            degree[x[0]]++;
        }

        queue<int> q;
        for(int i=0;i<n;i++){
            if(degree[i]==0){
                q.push(i);
            }
        }

        while(!q.empty()){
            int front=q.front();
            q.pop();
            ans.push_back(front);
            for(auto x:adj[front]){
                degree[x]--;
                if(degree[x]==0){
                    q.push(x);
                }
            }
        }
        if(ans.size()==n){
            return ans;
        }
        return {};
    }
