  if (!map.containsKey(index)) {
      return false;
  }

  List<String> list = map.get(index);
  for(String s : list) { 
      if(isSame(s, word)) { // when word has '.'
          return true;
      }
  }
  return false;
}

public boolean isSame(String s, String word) { // word has '.'
