class Solution {
public:
    int calculate(string& s) {
        auto precedence = [](char c){return c == '*' || c == '/';};
        stack<char> op;
		stack<int> num;
        int cur = 0;
        s += '#';                               // ensures all processing happens in loop...else we need to write an condition outside to take care of last number 
        for(auto c : s) 
            if(c == ' ') continue;
            else if(isdigit(c)) 
                cur = cur * 10 + (c-'0');            
            else {
                num.push(cur);                  // push the number formed till now 
                while(size(op) && precedence(c) <= precedence(op.top())) {  // evaluate operators in stack having precedence >= current operator
                    int num1 = num.top(); num.pop();
                    int num2 = num.top(); num.pop();
                    char curOp = op.top();  op.pop();

                    if(curOp == '*')        num.push(num2 * num1);
                    else if(curOp == '/')   num.push(num2 / num1);
                    else if(curOp == '+')   num.push(num2 + num1);
                    else if(curOp == '-')   num.push(num2 - num1);
                }   
                op.push(c);                     // push current operator to evaluate later
				cur = 0;                        // reset the number
            }

        return num.top();
    }
