    void travel (TreeNode* root, int &k, int &cnt, int &ans, bool &found) {
        if (found) return;
        if (!root) return;
        travel(root->left, k, cnt, ans, found);
        cnt++;
        if (k == cnt) {found = true; ans = root->val; }
        travel(root->right, k, cnt, ans, found);

