class Solution {
public:
    int lengthOfLIS(vector<int>& nums) 
    {
        int n = nums.size() ;
        vector<int> dp(n+1,1) ;
        int ans = 1 ;

        for(int index = 1 ; index < n ; index++)
        {
            for(int prev = index-1 ; prev >= 0 ; prev--)
                if(nums[prev] < nums[index])
                   dp[index] = max(1 + dp[prev],dp[index]) ;

            ans = max(ans,dp[index]) ;
        }

        return ans ;
    }
