/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    pair<int,int> solve(TreeNode* root){
        if(root == NULL){
            return {0,0};
        }

        pair<int,int> left = solve(root->left);
        pair<int,int> right = solve(root->right);

        pair<int,int> temp;
        temp.first = root->val + left.second + right.second;
        temp.second = max(left.first,left.second) + max(right.first,right.second);

        return temp;
    }

    int rob(TreeNode* root) {
        pair<int,int> ans = solve(root);
        return max(ans.first,ans.second);
    }
};,54,https://leetcode.com/problems/house-robber-iii,https://leetcode.com/problems/house-robber-iii/solutions/3955575/easy-recursive-solution-in-c/,117,337,cpp

