// Runtime: 3 ms, faster than 96.43% of C++ online submissions for Intersection of Two Arrays II.
class Solution {
public:
    vector<int> intersect(vector<int>& nums1, vector<int>& nums2) {
        // If the size of nums1 is greater than nums2, swap them...
        if(nums1.size() > nums2.size()) {
            swap(nums1, nums2);
        }
        // Create a hashmap to find out the intersection of two arrays...
        unordered_map<int,int> map;
        // Store the count of each element of one array using the Hash map...
        for(auto val: nums1) {
            map[val]++;
        }
        int idx = 0;
        // Traverse through the nums2 array....
        for(auto val: nums2) {
            // For each element in nums2, check if count of that element in nums1 is positive or not...
            // If count of nums2[idx] in array nums1 is positive, then add this element(nums2[idx]) in result array...
            if(map[val] > 0){
                nums1[idx++] = val;
                // Decrease the count of this element in Hash map.
                --map[val];
            }
        }
        return vector<int>(nums1.begin(), nums1.begin()+idx);
    }
};,120,https://leetcode.com/problems/intersection-of-two-arrays-ii,https://leetcode.com/problems/intersection-of-two-arrays-ii/solutions/2477252/very-easy-100-fully-explained-java-c-python-python3-hashmap-two-pointers/,123,350,cpp

var maxEnvelopes = function(envelopes) {
    // Sort envelopes by width in ascending order. If widths are equal, sort by height in descending order.
    envelopes.sort((a, b) => a[0] - b[0] || b[1] - a[1]);

    const lis = [envelopes[0][1]]; // Initialize LIS with the first height.

    for (let i = 1; i < envelopes.length; i++) {
        const height = envelopes[i][1];

        if (height > lis[lis.length - 1]) {
            lis.push(height);
        } else {
            // Find the correct position to update LIS.
            let left = 0;
            let right = lis.length - 1;
            while (left < right) {
                const mid = Math.floor((left + right) / 2);
                if (lis[mid] < height) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }
            lis[left] = height;
        }
    }

    return lis.length;
};
