class Solution {
public:
    int characterReplacement(string s, int k) {
        // Base case...
        if (s.size() == 0) return 0;
        // Make an array...
        vector <int> arr(128);
        // Initialize largestCount & beg pointer...
        int beg = 0, largestCount = 0;
        // Traverse all characters through the loop...
        for (int end = 0; end < s.size(); end++) {
            // Get the largest count of a single, unique character in the current window...
            largestCount = max(largestCount, ++arr[s[end]]);
            // We are allowed to have at most k replacements in the window...
            // So, if max character frequency + distance between beg and end is greater than k...
            // That means we have met a largest possible sequence, we can move the window to right...
            if (end - beg + 1 - largestCount > k)       // The main equation is: end - beg + 1 - largestCount...
                arr[s[beg++]]--;
        }
        // Return the sequence we have passes, which is s.length() - beg...
        return s.length() - beg;
    }
};,120,https://leetcode.com/problems/longest-repeating-character-replacement,https://leetcode.com/problems/longest-repeating-character-replacement/solutions/2524523/easy-100-fully-explained-c-java-python-javascript-python3-sliding-window/,149,424,cpp

class Solution {
public:
    Node* construct(vector<vector<int>>& grid) {
        int n = (int) grid.size();
        return build(grid, 0, 0, n);
    }

    Node* build(vector<vector<int>>& grid, int i, int j, int n) {
        if(n == 1) return new Node(grid[i][j], true);
        Node* res = new Node(0, false, 
                            build(grid, i, j, n / 2),
                            build(grid, i, j + n / 2, n / 2),
                            build(grid, i + n / 2, j, n / 2),
                            build(grid, i + n / 2, j + n / 2, n / 2));
        if(
            res->topLeft->isLeaf && 
            res->topRight->isLeaf && 
            res->bottomLeft->isLeaf && 
            res->bottomRight->isLeaf && 
            res->topLeft->val == res->topRight->val && 
            res->topLeft->val == res->bottomLeft->val && 
            res->topLeft->val == res->bottomRight->val
        ) {
            res->val = res->topLeft->val;
            res->isLeaf = true;
            delete res->topLeft;
            delete res->topRight;
            delete res->bottomLeft;
            delete res->bottomRight;
            res->topLeft = NULL;
            res->topRight = NULL;
            res->bottomLeft = NULL;
            res->bottomRight = NULL;
        }
        return res;
    }
