class Solution {
public:
    vector<int> nextGreaterElements(vector<int>& nums) {
        //idea is to go for next gtreater in nums+nums
        int n=nums.size();
        nums.resize(2*n);
        for(int i=n;i<2*n;i++){
            nums[i]=nums[i-n];
        }
        vector<int>res(n);
        stack<int>st;
        for(int i=nums.size()-1;i>=0;i--){
            while(!st.empty() && nums[i]>=nums[st.top()]){
                st.pop();
            }
            int idx=i%n;
            res[idx]=st.empty()?-1:nums[st.top()];
            st.push(i);
        }
        return res;
    }
