class Solution {
public:
    using fun = function<int(int, int)>;
    using Map = unordered_map<int, unordered_map<int, int>>;
    int findRotateSteps(string ring, string key, int INF = 1e9 + 7, Map m = {}) {
        int M = ring.size(),
            N = key.size();
        auto steps = [=](auto i, auto k) {
            return min(abs(i - k), M - abs(i - k)); // ⭐️ minimum x steps to rotate the ring from i..k (🚫 without wrap-around, ✅ with wrap-around)
        };
        fun go = [&](auto i, auto j) {
            if (m[i][j])
                return m[i][j];     // 🤔 memo
            if (j == N)
                return m[i][j] = 0; // 🛑 base case
            auto best = INF;
            for (auto k{ 0 }; k < M; ++k) // pre i (optimal k-th value is found as the recursive stack unwinds)
                if (ring[k] == key[j])
                    best = min(best, 1 + steps(i, k) + go(k, j + 1)); // 🎯 min steps to reach key[j] from each ring[i] is the min steps to reach key[j + 1] from ring[k], 🔍 find optimal k via exhaustive search
            return m[i][j] = best;
        };
        return go(0, 0); // 🚀 when the ring starts at i = 0 (ie. index 0 is aligned with the 12:00 direction of the ring) return the min steps to construct key[j = 0..N - 1]
    }
};,177,https://leetcode.com/problems/freedom-trail,https://leetcode.com/problems/freedom-trail/solutions/1147789/the-art-of-dynamic-programming/,179,514,cpp

def longest_palindrome_subseq(s)
    dp, dp_nxt = 2.times.collect {|i| Array.new(s.size, 0) }
    (s.size - 1).downto(0) {|i|
        dp_nxt[i] = 1
        (i+1...s.size).each {|j|
            dp_nxt[j] = (s[i] == s[j]) ? dp[j-1] + 2 : [dp[j], dp_nxt[j-1]].max
        }
        dp, dp_nxt = dp_nxt, dp
    }
    dp.last
end
