var scheduleCourse = function (a) {
  // duration, endDate
  a.sort((a, b) => a[1] - b[1]); // sort endDate asc

  let currtime = 0;
  let goodCourseDurations = [];
  for (let [d, e] of a) {
    if (currtime + d <= e) {
      goodCourseDurations.push(d);
      currtime += d;
    } else {
      // max pq is best to use here
      let maxd = Math.max(...goodCourseDurations);
      if (maxd > d) {
        let maxdIndex = goodCourseDurations.indexOf(maxd);
        goodCourseDurations[maxdIndex] = d;

        currtime -= maxd;
        currtime += d;
      }
    }
  }
  return goodCourseDurations.length;
