class Solution {
public:
    int maxProfit(vector<int>& prices, int fee) {
        int n = prices.size();
        vector<int> curr(2), next(2);

        next[1] = next[0] = 0; // base case
        /*
            curr[0] -> dp[i][0]
            curr[1] -> dp[i][1]

            next[0] -> dp[i+1][0]
            next[1] -> dp[i+1][1]
        */

        for (int i=n-1; i>=0; i--) {
            for (int buy=0; buy<=1; buy++) {
                if (buy) {
                    int x = next[0] - prices[i] - fee; // buy
                    int y = next[1]; // don't buy
                    curr[buy] = max(x, y);
                }
                else {
                    int x = next[1] + prices[i]; // sell
                    int y = next[0]; // don't sell
                    curr[buy] = max(x, y);
                }

            }
            next = curr;
        }

        return next[1];
    }
