class Solution {
    public int shortestPathLength(int[][] graph) {
        int n=graph.length;
        Queue<int[]> q=new LinkedList<>(); // curr_node, vis_mask
        Integer[][] dp=new Integer[n][1<<n];
        for(int i=0;i<n;i++) {
            q.add(new int[]{i, 1<<i});
            dp[i][1<<i]=0;
        }

        while(!q.isEmpty()) {
            int[] pop=q.poll();
            for(int neigh: graph[pop[0]]) {
                int vis_mask=pop[1] | (1<<neigh), dist=dp[pop[0]][pop[1]]+1;
                if(dp[neigh][vis_mask]==null || dp[neigh][vis_mask] > dist) {
                    if(vis_mask==(1<<n)-1) return dist; 
                    dp[neigh][vis_mask]=dist;
                    q.add(new int[]{neigh, vis_mask});
                }
            }
        }
        return 0;
    }
