class Solution {
    public int shortestSubarray(int[] nums, int k) {
        int n = nums.length;
        long[] pref = new long[n+1];
        for(int i=0; i<n; i++)
            pref[i+1] = pref[i] + nums[i]; //taking one extra index to get the ans when subarray starts from 0 to i
        // this way keeping 0 at start and moving every index by 1 we can get the prefix sum with min length

        int min = n+1;
        Deque<Integer> queue = new LinkedList(); 

        for(int i=0; i<=n; i++){
			// BASE - We always want something min to be deleted from our sum, so no point in keeping larger sums at earlier indices
			// EXPLANATION - 
            // if at any point a negative is coming then we will remove all sums before negative which are greater than this curr sum
            // because 
			// 1. if at any point in future i cannot get sum with this sum, i will not get sum from the number greater than this sum
            // Eg. -> 2 3 4 2... 9.. for 9 if i is not able to get the sum with 2, i won't be able to get the sum with 3,4, so remove them when 2 came!
            // 2. Also if i was to get target sum then this is the smallest index array size that i can get.
            // Eg. -> 2 3 4 2... 9.. If I am getting req sum with 2, then 3,4 are unnecessary increasing the size of subarray
            // 3. Array will simply now take whatever is smallest in queue. i.e. why are maintaining increasing queue
            while(!queue.isEmpty() && pref[i] <= pref[queue.getLast()])
                queue.removeLast();
            // checking all the lengths making sure sum >=k and if found then this is obvious any future i will give more lengths with this start index
            while(!queue.isEmpty() && pref[i] - pref[queue.getFirst()] >= k)
                min = Math.min(min, i - queue.removeFirst());
            queue.addLast(i);
        }

        return min <= n? min : -1;
    }
