            }
            if(nums[i]==0)
            {
                if(k>0)
                {
                    count++;
                    k--;
                }
                else{
                   while(k==0)
                   {
                       if(nums[start]==0)
                       {
                           start++;
                           k++;
                           count--;
                       }
                       else{
                           start++;
                           count--;
                       }
                   }
                   count++;
                   k--;

                }
            }
            max_count=max(max_count,count);
        }
        return max_count;
    }
