class Solution {
public:
    int maxSumTwoNoOverlap(vector<int>& nums, int firstLen, int secondLen) {
        int n = nums.size();
        vector<pair<int, int>> first, second;

        int s = 0, x = 0, ans1 = 0, ans2 = 0;
        for(int i=0; i<n; i++) {
            s += nums[i];
            if(i - x + 1 == firstLen) first.push_back({s, i}), s -= nums[x++];
        }
        s = 0, x = 0;
        for(int i=0; i<n; i++) {
            s += nums[i];
            if(i - x + 1 == secondLen) second.push_back({s, i}), s -= nums[x++];
        }

        for(int i=0; i<first.size(); i++) {
            int val = first[i].first, end = first[i].second;
            for(int j=0; j<second.size(); j++) {
                if(end < second[j].second - secondLen + 1) ans1 = max(ans1, val + second[j].first);
            }
        }
        for(int i=0; i<second.size(); i++) {
            int val = second[i].first, end = second[i].second;
            for(int j=0; j<first.size(); j++) {
                if(end < first[j].second - firstLen + 1) ans2 = max(ans2, val + first[j].first);
            }
        }
        return max(ans1, ans2);
    }
    // (0,0) (6,1) (5,2) (2,3) (2,4) (5,5) (1,6) (9,7) (4,8)
    // (6,1) (11,2) (7,3) (4,4) (7,5) (6,6) (10,7) (13,8)
