class Solution {
public:
    int findInMountainArray(int target, MountainArray &mountainArr) {
        int n = mountainArr.length();
        int maxPosition = -1;
        int left = 1;
        int right = n - 2;
        int mid;

        while (left < right) {
            mid = left + (right - left) / 2;
            if (mountainArr.get(mid) < mountainArr.get(mid + 1)) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        maxPosition = left;
        left = 0;
        right = maxPosition;
        int me;

        while (left <= right) {
            mid = left + (right - left) / 2;
            me = mountainArr.get(mid);

            if (me == target) return mid;
            if (me > target) right = mid - 1;
            else left = mid + 1;
        }
        left = maxPosition;
        right = n - 1;

        while (left <= right) {
            mid = left + (right - left) / 2;
            me = mountainArr.get(mid);

            if (me == target) return mid;
            if (me < target) right = mid - 1;
            else left = mid + 1;
        }
        return -1;
    }
};,52,https://leetcode.com/problems/find-in-mountain-array,https://leetcode.com/problems/find-in-mountain-array/solutions/4159123/beats-100-video-solution-java-c-python/,299,1185,cpp

/**
 * // This is MountainArray's API interface.
 * // You should not implement it, or speculate about its implementation
 * interface MountainArray {
 *     public int get(int index) {}
 *     public int length() {}
 * }
 */

class Solution {

    static int searchInc(MountainArray arr, int st, int end, int target){

        int ans = -1;
        while(st<=end){
            int mid = st + (end-st)/2;
            int a = arr.get(mid);

            if(a==target){
                ans = mid;
                end = mid-1;
            }else if(a>target){
                end=mid-1;
            }else st = mid+1;
        }
        return ans;
    }

    static int searchDec(MountainArray arr, int st, int end, int target){

        int ans = -1;
        while(st<=end){
            int mid = st + (end-st)/2;
            int a = arr.get(mid);

            if(a==target){
                ans = mid;
                end = mid-1;
            }else if(a>target){
                st=mid+1;
            }else end = mid-1;
        }
        return ans;
    }

    public int findInMountainArray(int target, MountainArray arr) {

        int n = arr.length();
        int i = 0;
        int j = n-1;
        int peak = -1;

        while(i<=j){
            int mid = i+(j-i)/2;
            if(mid==0){
                i=mid+1;
                continue;
            }
            if(mid==n-1){
                j=mid-1;
                continue;
            }
            int a = arr.get(mid);
            int l = arr.get(mid-1);
            int r = arr.get(mid+1);

            if(a>l && a>r){
                peak = mid;
                break;
            }else if(a>l && a<r) i = mid+1;
            else j = mid-1;
        }

        int a = searchInc(arr,0,peak,target);
        int b = searchDec(arr,peak,n-1,target);

        if(a==-1 && b==-1) return -1;
        else if(a==-1) return b;
        else if(b==-1) return a;
        else return Math.min(a,b);
    }
