            return dp[l][r];

        int ans = INT_MAX;
        for(int i=l;i<r;i++)
        {
            ans = min({long(ans) , (long)mp[{l,i}]*mp[{i+1,r}]+solve(a,l,i,mp,dp) + solve(a,i+1,r,mp,dp)});
