        for(int i=0;i<n;i++)
        {
            mp[{i,i}] = a[i];
            for(int j=i+1;j<n;j++)
            {
                mp[{i,j}] = max(mp[{i,j-1}],a[j]);
            }
        }


        vector<vector<int>> dp(n+1,vector<int>(n+1,-1));

        return solve(a,0,n-1,mp,dp);



