class Solution {
public:
    int mod = 1e9+7;
    int solve(int n,int &k,int x,vector<vector<int>> &dp){
        if(n==0&&x==0)return 1;
        if(n<=0)return 0;
        if(dp[n][x] != -1)return dp[n][x];
        int ans = 0;
