class Solution {
public:

    vector<vector<int>> dp;

    int helper(int n, int k, int t){
        if(n==0 && t==0) return 1;
        if(n<=0 || t<=0) return 0;


        if(dp[n][t]!=-1) return dp[n][t];

        int ans = 0;
        for(int i=1; i<=k; i++){
