var distanceBetweenBusStops = function(distance, start, destination) {
    let totalDistance = 0;
    let output = 0;

    for (let i = 0; i < distance.length; i++) {
        totalDistance += distance[i];

        if (start < destination) {
            if (i + 1 > start && i + 1 <= destination) {
                output += distance[i];
            }
        } else if (start > destination) {
            if ((i + 1 <= destination) || (i + 1 > start)) {
                output += distance[i];
            }
        } else {
            return 0;
        }
    }

    return Math.min(output, totalDistance - output);
