            subsets(arr, i+1, currString + arr.get(i));
        }
    }

    private boolean hasUniqueChars(String s){

        boolean[] map = new boolean[26];
        for(char c : s.toCharArray()){
            if(map[c-'a']){
                return false; 
            } 
            map[c-'a'] = true; 
        }
        return true; 
    }
