class Solution {
public:
    vector<int> parent;

    bool findParent(int n, vector<int>& leftChild, vector<int>& rightChild) {
        #pragma unroll
        for (int i=0; i < n; i++) {
            int left = leftChild[i], right=rightChild[i];
            if (left != -1) {
                if (parent[left]!=-1||left==i) {
                    return 0;
                }
                parent[left]=i;
            }
            if (right !=-1) {
                if (parent[right]!=-1||right==i) {
                    return 0;
                }
                parent[right]=i;
            }
        }
        return 1;
    }

    vector<int> root;

    int findRoot(int i) {
        if (parent[i]==-1) 
            return i;

        if (root[i]!=-1) return root[i];
        // Mark the node as visited during this call
        root[i]=-2; //for detecting cycle
        return root[i]=findRoot(parent[i]);
    }

    bool validateBinaryTreeNodes(int n, vector<int>& leftChild, vector<int>& rightChild)
    {
        parent.assign(n, -1);
        bool yes=findParent(n, leftChild, rightChild);
        if (!yes) return 0;

        root.assign(n, -1);
        int R0=findRoot(0);
        if (R0==-2||parent[R0]!=-1) return 0;
        #pragma unroll
        for (int i = 0; i<n; i++) {
            if (root[i]==-1) {
                int R=findRoot(i);
                if (R==-2||R!=R0||parent[R]!=-1) return 0;//Root shouldn't have a parent.
            }
        }
        return 1;
    }
};
,49,https://leetcode.com/problems/validate-binary-tree-nodes,https://leetcode.com/problems/validate-binary-tree-nodes/solutions/4178596/c-parents-dfs-finds-root-vs-kahn-s-algorithm/,353,1275,cpp

class Solution {
public:
    // time/space: O(n)/O(n)
    bool validateBinaryTreeNodes(int n, vector<int>& leftChild, vector<int>& rightChild) {
        // find the parent for each node
        unordered_map<int, int> node2parent;
        for (int node = 0; node < n; node++) {
            if (leftChild[node] != -1) {
                // each node must have only 1 parent
                if (node2parent.count(leftChild[node]) != 0) return false;
                node2parent[leftChild[node]] = node;
            }
            if (rightChild[node] != -1) {
                // each node must have only 1 parent
                if (node2parent.count(rightChild[node]) != 0) return false;
                node2parent[rightChild[node]] = node;
            }
        }

        // find the root of the binary tree
        int root = -1;
        for (int node = 0; node < n; node++) {
            // a root node has no parent
            if (node2parent.count(node) == 0) {
                // return false if there are more than 1 root
                if (root != -1) return false;
                root = node;
            }
        }
        // no root is found
        if (root == -1) return false;

        // travel the binary tree from the root, there must be no cycle
        vector<bool> visited(n, false);
        if (hasCycle(root, leftChild, rightChild, visited)) return false;

        // all nodes must be visited
        for (int node = 0; node < n; node++) {
            if (!visited[node]) return false;
        }

        return true;
    }
private:
    bool hasCycle(int node, vector<int>& leftChild, vector<int>& rightChild, vector<bool>& visited) {
        // terminate
        if (node == -1) return false;
        if (visited[node]) return true;
        visited[node] = true;

        // enumerate
        bool is_left_cycle = hasCycle(leftChild[node], leftChild, rightChild, visited);
        bool is_right_cycle = hasCycle(rightChild[node], leftChild, rightChild, visited);
        return (is_left_cycle || is_right_cycle);
    }
};,111,https://leetcode.com/problems/validate-binary-tree-nodes,https://leetcode.com/problems/validate-binary-tree-nodes/solutions/4177174/c-find-parent-and-root-and-detect-cycle/,354,1275,cpp

class Solution {
public:
    vector<int> fact(int n) {
        for (int i = sqrt(n); i > 1; i--) if (!(n % i)) return {i, n/i};
        return {1, n};
    }

