        vector<int>ad[n+1];
        c_t=time;
        for(auto x:edges){
            ad[x[0]].push_back(x[1]);
            ad[x[1]].push_back(x[0]);
        }
        vector<int>vis(n+1,0);
        dfs(ad,1,0,x,vis,1);
        if(ad[1].size()==0 && x==1)return 1.0;
       return ans;
    }
