class Solution {
    public int minStartValue(int[] nums) {
        // declare min value for our minimum start value
        int min = 0;
        // declare prefix sum
        int prefix = 0;
        // iterate over nums array
        for(int i = 0; i < nums.length; i++) {
            // calculate prefix sum on each step
            prefix += nums[i];
            // find min start value
            min = Math.min(min, prefix);
        }
        // return absolute value of start value and add 1
        return Math.abs(min) + 1;
    }       
