var findMinFibonacciNumbers = function (k) {
  let f = 0
  let s = 1
  let fib = [f, s]

  let t = f + s // ================= its sum of previous values
  for (; t <= k; t = f + s) {
    fib.push(t)
    f = s
    s = t
  }

  let cc = 0
  while (fib.length) {
    let x = fib.pop()
    while (k > 0 && x <= k) {
      k -= x // ================= do reverse - remove previous values from sum
      cc++
    }
  }
  return cc
}
