class Solution {
public:
    int maxScore(vector<int>& cardPoints, int k) {
        int n=cardPoints.size();
        if(k==n){
            return accumulate(cardPoints.begin(),cardPoints.end(),0);
        }
        int start=accumulate(cardPoints.begin(),cardPoints.begin()+k,0);
        int end=start;
        for(int i=k-1;i>=0;i--){
            end-=cardPoints[i];
            end+=cardPoints[n+i-k];
            start=max(start,end);
        }
        return start;
    }
