    void fun(string s,int count)
    {
        //cout<<s<<endl;
        if(s.length()==0)
        {
            ans=max(ans,count);
            return;
        }
        string first="";
        string second="";

        for(int i=0;i<s.length();i++)
        {
            first.push_back(s[i]);

            if(st.find(first)==st.end())   //first entry of this type of string
            {
                st.insert(first);
                second = s.substr(i+1,s.length());
                fun(second,count+1);
                st.erase(first);         //backtraing
            }	
            else
