var countConsistentStrings = function(allowed, words) {
    const hashmap = new Map();
    let output = 0;

    for (let i = 0; i < allowed.length; i++) {
        hashmap.set(allowed[i], 1);
    }

    for (let i = 0; i < words.length; i++) {
        const word = words[i];
        output++;
        for (let j = 0; j < word.length; j++) {
            if (!hashmap.has(word[j])) {
                output--;
                break;
            }
        }
    }

    return output;
