// Author: github.com/lzl124631x
// Time: O(N)
// Space: O(1)
class Solution {
public:
    int waysToSplit(vector<int>& A) {
        long mod = 1e9+7, ans = 0;
        for (int i = 1; i < A.size(); ++i) A[i] += A[i - 1];
        long N = A.size(), i = 0, j = 0, k = 0;
        for (; i < N; ++i) {
            long left = A[i];
            j = max(i + 1, j); // `j` is at least one greater than `i`.
            while (j < N && A[j] - left < left) ++j; // find the smallest `j` that satisfies `mid >= left`
            if (j >= N) break; // No room for `k`. Break
            k = max(k, j);
            while (k < N - 1 && A.back() - A[k] >= A[k] - A[i]) ++k;
            ans = (ans + k - j) % mod;
        }
        return ans;
    }
};,172,https://leetcode.com/problems/ways-to-split-array-into-three-subarrays,https://leetcode.com/problems/ways-to-split-array-into-three-subarrays/solutions/999795/c-3-pointers-o-n-time-o-1-space/,444,1831,cpp

class Solution {
public:
    int totalMoney(int n) {
        int k = n / 7;      // Calculate the number of complete weeks
        int F = 28;         // Initial earning for the first week
        int L = 28 + (k - 1) * 7;  // Earning for the last week
        int arithmeticSum = k * (F + L) / 2;  // Calculate the total earnings from complete weeks using arithmetic series formula

        int monday = 1 + k;  // Earnings on Monday for the final week
        int finalWeek = 0;

        // Calculate earnings for the final incomplete week
        for (int day = 0; day < n % 7; day++) {
            finalWeek += monday + day;  // Increment earnings for each day of the final incomplete week
        }

        return arithmeticSum + finalWeek;  // Return the total earnings for 'n' days
    }
};


