class Solution:
    def minTrioDegree(self, n, edges):
        # Create an adjacency matrix to represent the graph.
        am = [[0] * (n + 1) for _ in range(n + 1)]
        # Create a list to store the degree of each node.
        cnt = [0] * (n + 1)
        # Initialize the result as positive infinity.
        res = float('inf')

        # Fill the adjacency matrix and count degrees.
        for e in edges:
            am[min(e[0], e[1])][max(e[0], e[1])] = 1
            cnt[e[0]] += 1
            cnt[e[1]] += 1

        # Loop through all possible trios of nodes.
        for t1 in range(1, n + 1):
            for t2 in range(t1 + 1, n + 1):
                if am[t1][t2]:
                    for t3 in range(t2 + 1, n + 1):
                        if am[t1][t3] and am[t2][t3]:
                            # Calculate the degree of the trio and update the result.
                            res = min(res, cnt[t1] + cnt[t2] + cnt[t3] - 6)

        # If no trio with a common edge was found, return -1.
        return -1 if res == float('inf') else res
