class Solution {
public:
    int solve(int chota_sum,vector<int> &chota_array,int bada_sum,vector<int> &bada_array)
    {
        int i = bada_array.size()-1;
        int j = 0;
        int count = 0;
        while(true)
        {
            if(bada_sum<=chota_sum)
            {
                break;
            }
            int chota_change = -1;
            int bada_change = -1;

            if(i>=0)
            {
                bada_change = (bada_array[i]-1);
            }
            if(j<chota_array.size())
            {
                chota_change = (6-chota_array[j]);
            }
            if(bada_change>=chota_change)
            {
                bada_sum-=bada_change;
                i--;
                count++;
            }
            else
            {
                chota_sum+=chota_change;
                j++;
                count++;
            }
        }
        return count;
    }
    int minOperations(vector<int>& nums1, vector<int>& nums2) {
        int nums1mn = nums1.size();
        int nums1mx = nums1.size()*6;
        int nums2mn = nums2.size();
        int nums2mx = 6*nums2.size();

        if(nums1mn<=nums2mn)
        {
            if(nums1mx<nums2mn)
            return -1;
        }
        else
        {
            if(nums2mx<nums1mn)
            return -1;
        }
        sort(nums1.begin(),nums1.end());
        sort(nums2.begin(),nums2.end());

        int sum1 = 0;
        int sum2 = 0;
        for(int i=0;i<nums1.size();i++)sum1+=nums1[i];
        for(int i=0;i<nums2.size();i++)sum2+=nums2[i];

        int chota_sum;
        int bada_sum;

        chota_sum = min(sum1,sum2);
        bada_sum = max(sum1,sum2);

        if(chota_sum==bada_sum)
        return 0;

        if(chota_sum==sum1)
        {
            return solve(chota_sum,nums1,bada_sum,nums2);
        }
        else
        {
            return solve(chota_sum,nums2,bada_sum,nums1);
        }
    }
