    def maxAverageRatio(self, classes, extraStudents):
        def profit(a, b):
            return (a + 1) / (b + 1) - a / b

        maxHeap = []
        for a, b in classes:
            a, b = a * 1.0, b * 1.0  # Convert int to double
            maxHeap.append((-profit(a, b), a, b))
        heapq.heapify(maxHeap)  # Heapify maxHeap cost O(N)

        for _ in range(extraStudents):
            d, a, b = heapq.heappop(maxHeap)
            heapq.heappush(maxHeap, (-profit(a + 1, b + 1), a + 1, b + 1))

        return sum(a / b for d, a, b in maxHeap) / len(classes),33,https://leetcode.com/problems/maximum-average-pass-ratio,https://leetcode.com/problems/maximum-average-pass-ratio/solutions/1108263/python-java-max-heap-clean-concise/,464,1917,python

class Solution {
public:
    int maximumScore(vector<int>& nums, int k) {
        int n=nums.size();
        if (n == 1) return nums[0];
        int minN=nums[k], i=k, j=k, ans=INT_MIN;
        while (i>0 || j<n-1){
            if (i==0) j++;
            else if (j==n-1) i--;
            else if (nums[i-1]<nums[j+1]) j++;
            else i--;
            minN=min({minN, nums[i], nums[j]});
            ans=max(ans, minN*(j-i+1));
        }
        return ans;
    }
};
