class Solution {
public:
       int getNumberOfBacklogOrders(vector<vector<int>>& orders) {
        priority_queue<vector<int>>buy;
        priority_queue<vector<int>, vector<vector<int>>, greater<vector<int>>>sell;
        for (auto& o : orders) {
            if (o[2] == 0)
                buy.push(o);
            else
                sell.push(o);
            while (buy.size() && sell.size() && sell.top()[0] <= buy.top()[0]) {
                int k = min(buy.top()[1], sell.top()[1]);
                vector<int> tmp = buy.top(); buy.pop();
                tmp[1] -= k;
                if (tmp[1]) buy.push(tmp);

                tmp = sell.top(); sell.pop();
                tmp[1] -= k;
                if (tmp[1]) sell.push(tmp);
            }

        }
        int res = 0, mod = 1e9 + 7;
        while (sell.size())
            res = (res + sell.top()[1]) % mod, sell.pop();
        while (buy.size())
            res = (res + buy.top()[1]) % mod, buy.pop();
        return res;
    }
};,57,https://leetcode.com/problems/number-of-orders-in-the-backlog,https://leetcode.com/problems/number-of-orders-in-the-backlog/solutions/2835129/c-easy-fast/,469,1928,cpp

class Solution {
public:
    long calc(long n) //sum of numbers from [1 to n]
    {
        return ((n * (n + 1)) / 2);
    }
    //=========================================================================================
    long getSum(int totalLen, int val)
    {
        long totalSum = 0;
        int decreasingLen = val; //count of decreasing elements [val, val - 1, .., 1]

        //[val, val - 1, val - 2, ... 1, 1, 1, 1]
        if (totalLen >= decreasingLen)
        {
            long currSum = calc(val);
            int remainingSum = totalLen - decreasingLen; //all 1's
            totalSum = currSum + remainingSum;
        }
        else //[val, val - 1, val - 2]
        {
            long lastVal = decreasingLen - totalLen;
            totalSum = calc(val) - calc(lastVal);
        }
        return totalSum; 
    }
    //===========================================================================================
    int maxValue(int n, int index, int maxSum) 
    {
        int low = 1, high = maxSum;
        int leftCount = index, rightCount = n - index - 1;
        int ans = -1;
        while(low <= high)
        {
            int mid = low + (high - low) / 2;
            //=====================================================
            long  leftSum = getSum(leftCount, mid - 1);
            long  rightSum = getSum(rightCount, mid - 1);
            long  totalSum = leftSum + mid + rightSum;
            //=======================================================
            if (totalSum > maxSum)
                high = mid - 1;
            else { ans = mid; low = mid + 1; }
        }
        return ans; 
    }
};
