public class Solution {
    public int CountNicePairs(int[] nums) {
        const int MOD = 1000000007;
        Dictionary<long, int> counts = new Dictionary<long, int>();

        foreach (int num in nums) {
            long reversed = ReverseNumber(num);
            long diff = (long)num - reversed;

            if (counts.ContainsKey(diff)) {
                counts[diff]++;
            }
            else {
                counts[diff] = 1;
            }
        }

        int nicePairsCount = 0;
        foreach (var kvp in counts) {
            long frequency = kvp.Value;
            nicePairsCount = (int)((nicePairsCount + frequency * (frequency - 1) / 2) % MOD);
        }

        return nicePairsCount;
    }

    private long ReverseNumber(int num) {
        long reversed = 0;
        while (num > 0) {
            int digit = num % 10;
            reversed = reversed * 10 + digit;
            num /= 10;
        }
        return reversed;
    }
