class Solution {
public:
   map<vector<int>, int> dp;
int dfs(vector<int>& cnt, int left) {
    auto it = dp.find(cnt);
    if (it != end(dp))
        return it->second;
    int res = 0, bz = cnt.size();
    for (auto j = 1; j < bz; ++j) {
        if (--cnt[j] >= 0)
            res = max(res, (left == 0) + dfs(cnt, (bz + left - j) % bz));
        ++cnt[j];
    }
    return dp[cnt] = res;
}
int maxHappyGroups(int bz, vector<int>& groups) {
    vector<int> cnt(bz);
    int res = 0;
    for (auto group : groups) {
        if (group % bz == 0)
            ++res;
        else if (cnt[bz - group % bz]) {
            --cnt[bz - group % bz];
            ++res;
        }
        else 
            ++cnt[group % bz];
    }
    return dfs(cnt, 0) + res;
}
};,57,https://leetcode.com/problems/maximum-number-of-groups-getting-fresh-donuts,https://leetcode.com/problems/maximum-number-of-groups-getting-fresh-donuts/solutions/2815736/c-easy-fast/,473,1924,cpp

class Solution {
public:
    int minAbsoluteSumDiff(vector<int>& nums1, vector<int>& nums2) {
        int ans=0, cnt=0, M=1e9+7;
        vector<int>v, v1;
        for(int i=0; i<nums1.size(); i++){
            v.push_back(abs(nums1[i]-nums2[i]));
            cnt=(cnt+abs(nums1[i]-nums2[i]))%M;
        }
        sort(nums1.begin(), nums1.end());
        for(int i=0; i<nums1.size(); i++){
            int pos=lower_bound(nums1.begin(), nums1.end(), nums2[i])-nums1.begin();
            if(pos==0){
                v1.push_back(abs(nums2[i]-nums1[pos]));
            }
            else if(pos==nums1.size()){
                v1.push_back(abs(nums2[i]-nums1[pos-1]));
            }
            else{
                v1.push_back(min(abs(nums2[i]-nums1[pos]), abs(nums2[i]-nums1[pos-1])));
            }
        }
        for(int i=0; i<nums1.size(); i++){
            ans=max(ans, v[i]-v1[i]);
        }
        return (cnt-ans+M)%M;
    }
};,127,https://leetcode.com/problems/minimum-absolute-sum-difference,https://leetcode.com/problems/minimum-absolute-sum-difference/solutions/2941546/c-binary-search-easy-approach/,474,1946,cpp

